  rectangle &quot;RADICE
(Cerchio 0)
━━━━━━
Brain dump
Pensiero libero
[INTERDITTO LLM]&quot; as Z0 #FFB3B3
  rectangle &quot;configuration/
(Cerchio 1)
━━━━━━
Secrets, tokens
Infra privata
[VIETATO LLM]&quot; as Z1 #FFB3B3
  rectangle &quot;office/\n(Cerchio 2)\n━━━━━━\nData editoriale\nArticoli, inquadrature\n[Visione filtrata]&quot; as Z2 #FFF3B3
  rectangle &quot;foundry/private/
(Cerchio 3)
━━━━━━
