&lt;li&gt;&lt;a href=&quot;#_perché_utilizzare_either&quot;&gt;Perché utilizzare Either ?&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_contesto&quot;&gt;Contesto&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_le_diverse_approcci&quot;&gt;Le diverse approcci&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
