&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;// Dans un fichier math.ts
export const add = (a: number, b: number): number =&amp;gt; a + b;

// Dans un autre fichier
