&lt;p&gt;Le promesse vengono utilizzate per eseguire operazioni asincrone.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Esempio di quota :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-typescript&quot; data-lang=&quot;typescript&quot;&gt;const promise = new Promise&amp;lt;string&amp;gt;((resolve) =&amp;gt; {
    // Code asynchrone ici
    resolve(&quot;Succès&quot;);
});

promise.then((result) =&amp;gt; {
    console.log(result);
});&lt;/code&gt;&lt;/pre&gt;
