        repellendus.
      &amp;lt;/p&amp;gt;
    &amp;lt;/details&amp;gt;
  &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;

&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
