&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#char&quot;&gt;stringhe di caratteri e caratteri&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#math&quot;&gt;numeri e matematica&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#date&quot;&gt;date e ore&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#java8date&quot;&gt;date e ore java8&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;#arrCol&quot;&gt;array e collezioni&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
